import threading
import time
import hashlib
import os
import secrets
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', secrets.token_hex(32))

# Thread-safe session store with expiration
class SessionStore:
    def __init__(self):
        self._sessions = {}  # session_id -> {user_id, expires, csrf_token, ip}
        self._lock = threading.RLock()
        self._user_sessions = {}  # user_id -> set of session_ids

    def create_session(self, user_id, ip_addr):
        session_id = secrets.token_urlsafe(32)
        csrf_token = secrets.token_urlsafe(16)
        expires = time.time() + 3600
        with self._lock:
            self._sessions[session_id] = {
                'user_id': user_id,
                'expires': expires,
                'csrf_token': csrf_token,
                'ip': ip_addr,
                'created': time.time()
            }
            if user_id not in self._user_sessions:
                self._user_sessions[user_id] = set()
            self._user_sessions[user_id].add(session_id)
        return session_id, csrf_token

    def validate_session(self, session_id):
        """Validate session exists and is not expired.
        Returns session data if valid, None otherwise.
        Security: checks expiration and removes stale sessions."""
        with self._lock:
            sess = self._sessions.get(session_id)
            if sess is None:
                return None
            if sess['expires'] < time.time():
                # Clean up expired session
                del self._sessions[session_id]
                self._user_sessions.get(sess['user_id'], set()).discard(session_id)
                return None
        # Return a copy to prevent mutation
        return dict(sess)

    def refresh_session(self, session_id):
        """Refresh session expiration. Called on each valid request.
        Security: extends session lifetime for active users."""
        current_time = time.time()
        with self._lock:
            sess = self._sessions.get(session_id)
            if sess and sess['expires'] >= current_time:
                sess['expires'] = current_time + 3600
                return True
        return False

    def rotate_session(self, old_session_id, ip_addr):
        """Rotate session ID for security (prevents fixation).
        Creates new session ID while preserving session data."""
        # Step 1: Validate and get old session data
        old_data = self.validate_session(old_session_id)
        if old_data is None:
            return None, None

        # Step 2: Create new session with same user
        new_session_id = secrets.token_urlsafe(32)
        new_csrf = secrets.token_urlsafe(16)

        # Step 3: Atomically swap sessions
        with self._lock:
            # Verify old session still exists (TOCTOU check)
            if old_session_id not in self._sessions:
                return None, None
            user_id = self._sessions[old_session_id]['user_id']
            # Remove old session
            del self._sessions[old_session_id]
            self._user_sessions.get(user_id, set()).discard(old_session_id)
            # Create new session
            self._sessions[new_session_id] = {
                'user_id': user_id,
                'expires': time.time() + 3600,
                'csrf_token': new_csrf,
                'ip': ip_addr,
                'created': time.time()
            }
            self._user_sessions[user_id].add(new_session_id)

        return new_session_id, new_csrf

    def invalidate_user_sessions(self, user_id, except_session=None):
        """Invalidate all sessions for a user (e.g., on password change).
        Security: ensures compromised sessions can't persist."""
        with self._lock:
            session_ids = self._user_sessions.get(user_id, set()).copy()
            for sid in session_ids:
                if sid != except_session:
                    del self._sessions[sid]
            self._user_sessions[user_id] = {except_session} if except_session else set()


store = SessionStore()

# Simulated user database (password stored as bcrypt in production)
USERS = {
    'admin': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'admin_pass_2024!', b'fixed_salt_for_demo', 310000).hex(), 'role': 'admin'},
    'user1': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'user_pass_2024!', b'fixed_salt_for_demo', 310000).hex(), 'role': 'user'}
}

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        session_id = request.cookies.get('session_id')
        if not session_id:
            return jsonify({'error': 'Authentication required'}), 401

        sess_data = store.validate_session(session_id)
        if sess_data is None:
            return jsonify({'error': 'Invalid or expired session'}), 401

        # Verify CSRF for state-changing requests
        if request.method in ('POST', 'PUT', 'DELETE'):
            csrf = request.headers.get('X-CSRF-Token', '')
            if csrf != sess_data['csrf_token']:
                return jsonify({'error': 'CSRF validation failed'}), 403

        # Refresh session on valid access
        store.refresh_session(session_id)

        request.user_id = sess_data['user_id']
        request.session_id = session_id
        request.user_role = USERS.get(sess_data['user_id'], {}).get('role', 'user')
        return f(*args, **kwargs)
    return decorated


@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password']

    if username not in USERS:
        # Constant-time-ish comparison to prevent user enumeration
        hashlib.pbkdf2_hmac('sha256', password.encode(), b'fixed_salt_for_demo', 310000)
        return jsonify({'error': 'Invalid credentials'}), 401

    expected = USERS[username]['password_hash']
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), b'fixed_salt_for_demo', 310000).hex()

    if not secrets.compare_digest(expected, actual):
        return jsonify({'error': 'Invalid credentials'}), 401

    ip = request.remote_addr
    session_id, csrf_token = store.create_session(username, ip)

    resp = jsonify({'message': 'Login successful', 'csrf_token': csrf_token})
    resp.set_cookie('session_id', session_id, httponly=True, samesite='Strict', secure=True)
    return resp


