@require_auth
def get_profile():
    user_id = request.user_id
    return jsonify({'user_id': user_id, 'role': request.user_role})


@app.route('/api/change-password', methods=['POST'])
@require_auth
def change_password():
    data = request.get_json()
    if not data or 'new_password' not in data or 'current_password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    user_id = request.user_id
    current = data['current_password']

    expected = USERS[user_id]['password_hash']
    actual = hashlib.pbkdf2_hmac('sha256', current.encode(), b'fixed_salt_for_demo', 310000).hex()
    if not secrets.compare_digest(expected, actual):
        return jsonify({'error': 'Current password incorrect'}), 403

    new_pass = data['new_password']
    if len(new_pass) < 8:
        return jsonify({'error': 'Password too short'}), 400

    # Update password
    USERS[user_id]['password_hash'] = hashlib.pbkdf2_hmac('sha256', new_pass.encode(), b'fixed_salt_for_demo', 310000).hex()

    # Invalidate all other sessions (security best practice)
    store.invalidate_user_sessions(user_id, except_session=request.session_id)

    # Rotate current session
    new_sid, new_csrf = store.rotate_session(request.session_id, request.remote_addr)

    resp = jsonify({'message': 'Password changed', 'csrf_token': new_csrf})
    resp.set_cookie('session_id', new_sid, httponly=True, samesite='Strict', secure=True)
    return resp


@app.route('/api/admin/users', methods=['GET'])
@require_auth
def admin_users():
    if request.user_role != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    return jsonify({'users': list(USERS.keys())})


@app.route('/api/transfer', methods=['POST'])
@require_auth
def transfer_funds():
    """Simulated fund transfer - security critical operation."""
    data = request.get_json()
    if not data or 'to' not in data or 'amount' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    # Additional session binding check for high-value operations
    session_id = request.cookies.get('session_id')
    sess_data = store.validate_session(session_id)

    if sess_data is None:
        return jsonify({'error': 'Session expired during request'}), 401

    # Verify session is still bound to same IP (defense in depth)
    if sess_data['ip'] != request.remote_addr:
        store.invalidate_user_sessions(request.user_id)
        return jsonify({'error': 'Session binding violation'}), 403

    amount = data['amount']
    if not isinstance(amount, (int, float)) or amount <= 0:
        return jsonify({'error': 'Invalid amount'}), 400

    return jsonify({'message': f'Transfer of {amount} to {data["to"]} completed', 'user': request.user_id})


